{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The glass diver surveys the ruined city from a broken tower.",
      "visual_description": "A shattered tower overlooking a collapsed royal district, with torn banners flapping in the wind and the glass diver's helmet reflecting broken stained glass below.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 2,
      "caption": "Mara the cartographer consults her map at the city's edge.",
      "visual_description": "Mara kneels on a stone arch, compass in hand, studying a parchment map while the oracle lamp flickers beside her.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The oracle lamp warns of a cursed tower ahead.",
      "visual_description": "The lamp's flame eye glows intensely as it faces a dark spiral tower wrapped in ivy and rusted iron rings.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "A sleeping tax collector blocks the main gate.",
      "visual_description": "The massive iron gate is propped half-open, with the tax collector slumped against a ledger, stamp papers stuck to his sleeves, snoring softly.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 5,
      "caption": "The glass diver swims through a cracked window to bypass the gate.",
      "visual_description": "The glass diver presses against a fractured window pane, rippling like water as he passes through into a courtyard.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "The tin fox scouts ahead through rubble.",
      "visual_description": "The small metal fox picks its way over fallen columns, its key-wind tail ticking softly, blue glass eyes scanning the shadows.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 7,
      "caption": "Mara follows the tin fox into a plaza of old royal banners.",
      "visual_description": "Faded velvet banners hang from empty flagpoles, their crests torn, dust motes dancing in shafts of light as Mara steps carefully.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp reveals a hidden staircase beneath a banner.",
      "visual_description": "The lamp's glow casts long shadows, illuminating a stone trapdoor half-concealed by a fallen banner embroidered with a lion.",
      "characters": ["oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "The glass diver descends into the underground crypt.",
      "visual_description": "Cobwebbed stairs spiral down into a low chamber lined with rusted iron grilles and faint blue phosphorescence.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The sleeping tax collector is carried along, still asleep.",
      "visual_description": "The tin fox pulls the snoring collector by his ledger strap across a mosaic floor, his stamp papers trailing behind.",
      "characters": ["sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 11,
      "caption": "Mara finds a magic door inscribed with glowing runes.",
      "visual_description": "A tall door of black stone pulses with pale glyphs, its surface cold and smooth, set in a wall of broken marble.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The glass diver speaks the pass phrase from the map.",
      "visual_description": "The glass diver's helmet mists as he whispers ancient syllables; the runes flare and the door swings open silently.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "An armored patrol of clockwork figures marches past.",
      "visual_description": "Three metallic humanoids with blank visors and halberds clank across a distant colonnade, their movements jerky and synchronized.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The oracle lamp warns of a trap ahead.",
      "visual_description": "The lamp's eye narrows as it shines on a floor of pressure plates among scattered coins and armor pieces.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 15,
      "caption": "The glass diver leads the group across the trapped floor.",
      "visual_description": "The glass diver steps lightly on the plates, using reflections in his helmet to avoid triggers, as others follow his exact path.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 16,
      "caption": "They reach the escape bridge over a dry moat.",
      "visual_description": "A narrow stone bridge arches over a chasm filled with rusted spikes and debris, the far gate dimly visible.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The bridge begins to crumble as they cross.",
      "visual_description": "Cracks spider out from the bridge's center, stones falling away into the darkness, the tin fox scurrying ahead.",
      "characters": ["tin_fox", "glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the open plains beyond the city.",
      "visual_description": "The group emerges onto a grassy hillside, the ruined city behind them, the glass diver's helmet catching the first light of dawn.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "sleeping_tax_collector", "tin_fox"]
    }
  ]
}

